// Author: Navjyot Nishant
// Created: 2026-11-04
// Last updated: 2026-11-04
// Description: Embeds catalog.json so Go code can import the metric registry.

// Package devlake exposes the generated metric catalog to Go.
//
// The catalog is generated by build-catalog.py and checked by `make
// dashboards`. Embedding it from here, beside the file, means there is no
// second copy to drift: the bytes Go programs load are the bytes CI checks.
// Import it through pkg/registry, not directly.
package devlake

import _ "embed"

// CatalogJSON is catalog.json exactly as committed.
//
//go:embed catalog.json
var CatalogJSON []byte
